import{_ as t,o as d,c as o,a5 as a}from"./chunks/framework.CQwNn0Y-.js";const g=JSON.parse('{"title":"ZenFile API","description":"","frontmatter":{"title":"ZenFile API"},"headers":[],"relativePath":"docs/api.md","filePath":"docs/api.md","lastUpdated":1792245757000}'),s={name:"docs/api.md"};function n(c,e,i,r,l,p){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="zenfile-api" tabindex="-1">ZenFile API <a class="header-anchor" href="#zenfile-api" aria-label="Permalink to “ZenFile API”">​</a></h1><p>插件运行时协议。协议版本 <code>1</code>（<code>zenfile_core::PROTOCOL_VERSION</code>）。</p><div class="warning custom-block"><p class="custom-block-title">当前限制</p><p><strong>能力调用链路（<code>call</code> / <code>result</code>）尚未实现。</strong> 宿主侧读线程目前只认 <code>hello</code> 和 <code>beat</code>， 收到 <code>call</code> 不会真的分发给插件。</p><p>当前可验收的范围是：<strong>装得上、看得见、进程能拉起、能握手、能持续心跳、崩了能兜住</strong>。</p><p>同理，<code>zenfile-core/src/ipc.rs</code> 里的长度前缀帧（4 字节 LE 长度 + JSON）与 <code>Envelope</code> 枚举<strong>只在单元测试和自检里使用</strong>，是给后续演进预留的正式帧格式， <strong>不是</strong>当前生效的传输格式。</p></div><h2 id="命名管道" tabindex="-1">命名管道 <a class="header-anchor" href="#命名管道" aria-label="Permalink to “命名管道”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\\\.\\pipe\\ZenFile.&lt;pid&gt;.&lt;safe_id&gt;</span></span></code></pre></div><p><code>&lt;pid&gt;</code> 是<strong>插件自己的</strong> pid。用 pid 是为了让「重启同一个插件」天然换一条管道， 不会撞上上一条的残留。</p><div class="danger custom-block"><p class="custom-block-title">这里有个非常容易踩的坑</p><p>两侧<strong>必须调同一个函数</strong> <code>zenfile_core::plugin::pipe_name(pid, id)</code> 计算这个名字。 早期宿主侧直接拼原始 id、插件侧过滤过字符，id 带非安全字符时两边算出两个名字， 插件永远连不上。</p><p><code>safe_id</code> 的规则是：<code>[a-z0-9_-]</code> 保留，其余字符替换为 <code>_</code>。</p></div><h2 id="消息格式" tabindex="-1">消息格式 <a class="header-anchor" href="#消息格式" aria-label="Permalink to “消息格式”">​</a></h2><p>传输是<strong>换行（<code>\\n</code>）分隔的 JSON</strong>，一行一条消息。</p><table tabindex="0"><thead><tr><th><code>t</code></th><th>方向</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>hello</code></td><td>插件 → 宿主</td><td><code>{&quot;t&quot;:&quot;hello&quot;,&quot;id&quot;:...,&quot;protocol&quot;:1,&quot;argv&quot;:[...]}</code></td><td>握手，声明身份与协议版本</td></tr><tr><td><code>beat</code></td><td>插件 → 宿主</td><td><code>{&quot;t&quot;:&quot;beat&quot;}</code></td><td>心跳</td></tr><tr><td><code>shutdown</code></td><td>宿主 → 插件</td><td>—</td><td>插件收到后应干净退出，返回 <code>0</code></td></tr><tr><td><code>call</code></td><td>宿主 → 插件</td><td><code>{&quot;t&quot;:&quot;call&quot;,&quot;id&quot;:N,...}</code></td><td>一次能力调用，<strong>必须回响应</strong></td></tr><tr><td><code>result</code></td><td>插件 → 宿主</td><td><code>{&quot;t&quot;:&quot;result&quot;,&quot;id&quot;:N,&quot;ok&quot;:bool,&quot;payload&quot;:...}</code></td><td>对 <code>call</code> 的响应</td></tr></tbody></table><h3 id="三条必须遵守的协议纪律" tabindex="-1">三条必须遵守的协议纪律 <a class="header-anchor" href="#三条必须遵守的协议纪律" aria-label="Permalink to “三条必须遵守的协议纪律”">​</a></h3><ol><li><p><strong>心跳必须自己主动发，不能等宿主来问。</strong> 宿主判断「插件还活着」的唯一依据就是这条。 只在收到消息时才发心跳，宿主一安静就会误判卡死。间隔取超时的一半（<code>2500ms</code>）， 丢一拍不会被误杀。</p></li><li><p><strong>收到 <code>call</code> 必须回响应，哪怕回失败。</strong> 不回的话宿主那边挂着一个等不到的请求。</p></li><li><p><strong>读消息时半截 JSON 要留着等下一次。</strong> 管道是字节流，一次读拿到的很可能只是半条消息， 直接解析会报 <code>EOF while parsing</code>——那不是协议错误，只是正常分片。</p></li></ol><h3 id="connectnamedpipe-不能漏" tabindex="-1"><code>ConnectNamedPipe</code> 不能漏 <a class="header-anchor" href="#connectnamedpipe-不能漏" aria-label="Permalink to “ConnectNamedPipe 不能漏”">​</a></h3><div class="danger custom-block"><p class="custom-block-title custom-block-title-default">DANGER</p><p><strong><code>CreateNamedPipeW</code> 之后必须调 <code>ConnectNamedPipe</code>，否则数据永远不流动。</strong></p></div><p><code>CreateNamedPipeW</code> 只是造出一个「待连接」的实例；客户端 <code>CreateFileW</code> 挂上来的那一刻 连接还在排队状态，要 <code>ConnectNamedPipe</code> 才真正接通。</p><p>漏掉这一步的现象<strong>极具欺骗性</strong>：管道看起来存在、插件进程活着、没有任何错误日志， 但宿主一个字节都读不到——心跳永远停在初始值，5 秒后被判卡死。</p><p>客户端可能在 <code>ConnectNamedPipe</code> 之前就连上了，此时返回 <code>ERROR_PIPE_CONNECTED(535)</code>—— 那是<strong>成功</strong>，不是错误，别当失败处理。</p><h2 id="生命周期状态机" tabindex="-1">生命周期状态机 <a class="header-anchor" href="#生命周期状态机" aria-label="Permalink to “生命周期状态机”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>                     discover()  整个进程只做一次</span></span>
<span class="line"><span>                         │</span></span>
<span class="line"><span>                         ▼</span></span>
<span class="line"><span>   清单损坏 ──────────► Failed  (面板可见，不静默跳过)</span></span>
<span class="line"><span>                         │</span></span>
<span class="line"><span>   协议不符 ──────────► Failed  &quot;协议版本不兼容&quot;</span></span>
<span class="line"><span>                         │</span></span>
<span class="line"><span>                    拉起进程 ──► 拿到 pid ──► 建管道 ──► ConnectNamedPipe</span></span>
<span class="line"><span>                         │</span></span>
<span class="line"><span>                    Starting ──── 心跳超时 ──► Hung ──► kill ──► 重启</span></span>
<span class="line"><span>                         │</span></span>
<span class="line"><span>                  收到 hello（greeted）</span></span>
<span class="line"><span>                         ▼</span></span>
<span class="line"><span>                      Running</span></span></code></pre></div><p>崩溃处理在 100ms 定时器里：</p><ol><li>先判<strong>进程还在不在</strong>，再判心跳（顺序不能反，见 <a href="/zenfile/guide/plugins.html#崩溃隔离">插件页</a>）</li><li>进程没了 → 崩溃计数 +1 → 连续 4 次后停止重启（<code>MAX_RESTARTS = 3</code>）</li></ol><h2 id="能力" tabindex="-1">能力 <a class="header-anchor" href="#能力" aria-label="Permalink to “能力”">​</a></h2><table tabindex="0"><thead><tr><th>字符串</th><th>含义</th></tr></thead><tbody><tr><td><code>clipboard.history</code></td><td>读剪贴板历史</td></tr><tr><td><code>screenshot.capture</code></td><td>触发截图</td></tr><tr><td><code>taskmgr.snapshot</code></td><td>拉取进程 / 性能快照</td></tr><tr><td><code>terminal.open</code></td><td>在当前目录开终端</td></tr><tr><td><code>preview.open</code></td><td>请求预览文件</td></tr><tr><td><code>core.log</code></td><td>写一行日志</td></tr></tbody></table><p>能力名<strong>点号小写与 PascalCase 两种写法都收</strong>（<code>clipboard.history</code> 与 <code>ClipboardHistory</code> 等价）。写错时报错会列出全部可用名字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>未知能力 &quot;no.such.cap&quot;，可用：clipboard.history / screenshot.capture / ...</span></span></code></pre></div><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to “能力边界”">​</a></h2><p>插件进程里<strong>没有窗口、没有托盘、没有单实例互斥</strong>（<code>main.rs</code> 的 <code>--plugin</code> 分支在那些 逻辑之前就 <code>return</code>）。它拿不到宿主窗口句柄、托盘、别的插件的管道。</p><h2 id="相关源码" tabindex="-1">相关源码 <a class="header-anchor" href="#相关源码" aria-label="Permalink to “相关源码”">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>职责</th></tr></thead><tbody><tr><td><code>zenfile-core/src/plugin.rs</code></td><td>清单解析、状态机、进程生命周期、管道名计算</td></tr><tr><td><code>zenfile-core/src/process.rs</code></td><td><code>ProcessTree</code>（Job Object）、<code>spawn</code>、<code>terminate_pid</code>、<code>process_alive</code></td></tr><tr><td><code>zenfile-app/src/plugin_server.rs</code></td><td><strong>宿主侧</strong>管道 server</td></tr><tr><td><code>zenfile-app/src/plugin_host.rs</code></td><td><strong>插件侧</strong>：<code>PipeClient</code>、握手、心跳循环</td></tr><tr><td><code>zenfile-app/src/settings.rs</code></td><td>「插件」页绘制与开关</td></tr><tr><td><code>zenfile-core/src/ipc.rs</code></td><td>帧协议与 <code>Capability</code>（⚠️ 当前仅测试使用）</td></tr></tbody></table>`,29)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
